{
  "item_id": "PRISMA_2020_3",
  "elements": [
    {
      "element_id": "prisma_2020_3_e1",
      "status": "PRESENT",
      "chunk_id": "text_2",
      "quote": "Despite advances made in curbing the global malaria burden since the 2000s, progress has stalled, in part due to a plateauing of the financing available to implement needed interventions. In 2020, approximately 3.3 billion USD was invested globally for malaria interventions, falling short of the targeted 6.8 billion USD set by the GTS, increasing the financial gap between desirable and actual investment. Models for malaria control optimization are used to disentangle the most efficient interventions or packages of interventions for inherently constrained budgets.",
      "reason": "The text describes the current state of knowledge regarding malaria control, the financial gap, and the role of optimization models in addressing this."
    },
    {
      "element_id": "prisma_2020_3_e2",
      "status": "PRESENT",
      "chunk_id": "text_2",
      "quote": "This systematic review aimed to identify and characterise models for malaria control optimization for resource allocation in limited resource settings and assess their strengths and limitations.",
      "reason": "The review's objective is clearly stated, which explains the need for the review to identify and characterize these models."
    },
    {
      "element_id": "prisma_2020_3_e3",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "The manuscript does not indicate that this is an update or replication of a previous systematic review, nor does it mention the existence of similar systematic reviews that necessitate this specific one."
    },
    {
      "element_id": "prisma_2020_3_e4",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "This is a review of optimization models, not a review of the effects of a specific intervention."
    },
    {
      "element_id": "prisma_2020_3_e5",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "The review focuses on optimization models rather than evaluating a specific complex intervention or delivery context requiring a logic model."
    }
  ],
  "confidence": 100
}

{
  "item_id": "PRISMA_2020_4",
  "elements": [
    {
      "element_id": "prisma_2020_4_e1",
      "status": "PRESENT",
      "chunk_id": "text_6",
      "quote": "The research question for this review was ' Are there English-language publications in peer-reviewed scientific journals describing how models have been used to allocate resources for malaria interventions in limited resource settings?' The main aim of this review was to identify and characterize models for malaria control optimization for resource allocation in malaria control and elimination settings and to identify their strengths and limitations.",
      "reason": "The manuscript explicitly states the research question and the main aim of the review."
    },
    {
      "element_id": "prisma_2020_4_e2",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "This is a systematic review of models used for malaria control optimization, not a review of the effects of specific interventions; therefore, the requirement to state planned comparisons using PICO does not apply."
    }
  ],
  "confidence": 100
}

{
  "item_id": "PRISMA_2020_5",
  "elements": [
    {
      "element_id": "prisma_2020_5_e1",
      "status": "PRESENT",
      "chunk_id": "text_7",
      "quote": "Each record in the search were included if they met all of the following criteria: (1) Were scientific peer-reviewed journals written in English; (2) Were published before 30th June 2024; (3) Studies were included irrespective of the targeted geographical regions; (4) Studies were included irrespective of the population subgroups; (5) Studies containing an optimization model (mathematical or statistical); (6) All studies with human Plasmodium species; (7) Studies with two or more interventions; (8) Cost data were used in combination with the model outputs; (9) Outcomes/health benefits were clearly stated and/or measured.",
      "reason": "The manuscript explicitly lists the inclusion criteria, covering study type (peer-reviewed journals), language (English), publication date, population (human Plasmodium species), and specific model/intervention requirements."
    },
    {
      "element_id": "prisma_2020_5_e2",
      "status": "PRESENT",
      "chunk_id": "text_7",
      "quote": "(1) Were scientific peer-reviewed journals written in English; (2) Were published before 30th June 2024",
      "reason": "The manuscript specifies report characteristics including language (English) and publication date (before 30th June 2024). Exclusion criteria in text_9 further clarify report types (e.g., editorials, pre-prints)."
    },
    {
      "element_id": "prisma_2020_5_e3",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "The review does not appear to have excluded studies based on the distinction between outcomes not measured versus outcomes not reported; therefore, this conditional requirement is not applicable."
    },
    {
      "element_id": "prisma_2020_5_e4",
      "status": "PRESENT",
      "chunk_id": "text_10",
      "quote": "A narrative synthesis of the study characteristics was performed. All studies investigated WHO-recommended interventions for control or elimination targets (Table 2)... Of the twelve studies that used dynamic transmission models in combination with economic/cost models for optimization, six (40.0%) used compartmental models [16, 17, 28, 29, 32, 38], and the other six (40.0%) used individual-based models [18, 25, 33-35, 37]. Two (13.0%) studies used static models [10, 11] and one (7.0%) study used a linear regression model for their analysis (Fig. 2).",
      "reason": "The manuscript describes how studies were grouped for synthesis, specifically by model type (compartmental, individual-based, static, linear regression) and by intervention type (Table 2)."
    },
    {
      "element_id": "prisma_2020_5_e5",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "There are no notable restrictions on study eligibility that require a specific rationale beyond the standard inclusion/exclusion criteria provided."
    }
  ],
  "confidence": 100
}

